import numpy as np
from scipy import stats
from sklearn.cluster import AgglomerativeClustering

MAX_DRIVERS = 5

def design(feats):
    # Filter to significant features (p < 0.05)
    sig_idx = [i for i, fid in enumerate(feats.ids) if feats.types[i] != 'clinical']

    # If fewer than 2 features, return empty design
    if len(sig_idx) < 2:
        return Design(
            drivers=(),
            columns=(),
            products=(),
            loadings={}
        )

    # Compute correlation matrix for non-clinical features
    X = feats.x[:, sig_idx]

    # Handle case where all features are constant
    if np.all(X == X[0, :]):
        return Design(
            drivers=(),
            columns=(),
            products=(),
            loadings={}
        )

    # Compute correlation matrix
    corr = np.corrcoef(X.T)

    # Identify highly correlated pairs (|r| >= 0.6)
    pairs = []
    for i in range(len(sig_idx)):
        for j in range(i+1, len(sig_idx)):
            if abs(corr[i, j]) >= 0.6:
                pairs.append((feats.ids[sig_idx[i]], feats.ids[sig_idx[j]]))

    # Cluster features based on correlation
    if len(pairs) > 0:
        # Create adjacency matrix
        adj = np.zeros((len(sig_idx), len(sig_idx)))
        for a, b in pairs:
            try:
                i, j = feats.column(a), feats.column(b)
                if 0 <= i < len(sig_idx) and 0 <= j < len(sig_idx):
                    adj[i, j] = adj[j, i] = 1
            except:
                continue

        # Avoid clustering issues with single features
        if len(sig_idx) > 1:
            # Hierarchical clustering
            try:
                clustering = AgglomerativeClustering(
                    n_clusters=min(2, len(sig_idx)), 
                    affinity='precomputed', 
                    linkage='average'
                ).fit(1 - adj)

                # Select cluster with highest mean effect size
                clusters = {}
                for i, label in enumerate(clustering.labels_):
                    if label not in clusters:
                        clusters[label] = []
                    clusters[label].append(sig_idx[i])

                # Choose largest cluster
                if clusters:
                    best_cluster = max(clusters.values(), key=len)
                    module_ids = [feats.ids[i] for i in best_cluster]

                    # Compute weighted score using first principal component
                    module_data = feats.x[:, best_cluster]
                    _, _, v = np.linalg.svd(module_data, full_matrices=False)
                    loadings = dict(zip(module_ids, v[0]))

                    return Design(
                        drivers=module_ids[:MAX_DRIVERS],
                        columns=module_ids,
                        products=(),
                        loadings=loadings
                    )
            except:
                pass

    # No strong correlations found
    return Design(
        drivers=(),
        columns=(),
        products=(),
        loadings={}
    )

